#!/bin/bash
# prune_local <dir> <name> <keep>: remove name.N with N > keep.
prune_local() {
  local dir=$1 name=$2 keep=$3 f n
  for f in "$dir/$name".*; do
    [ -e "$f" ] || continue
    n=${f##*.}
    case $n in ''|*[!0-9]*) continue;; esac
    [ ${#n} -le 8 ] || continue
    [ "$n" -gt "$keep" ] && rm -f -- "$f"
  done
}
# prune_archive <archive dir> <name> <keep>: keep only the newest <keep> name.<stamp> (8 digits).
prune_archive() {
  local archive=$1 name=$2 keep=$3
  ls "$archive" | grep -E "^$(printf '%s' "$name" | sed 's/[.[\*^$]/\\&/g')\.[0-9]{8}$" | sort -r | tail -n +"$((keep + 1))" |
    while read -r f; do rm -f -- "$archive/$f"; done
}

